/*
 * A092782  The ternary tribonacci word; also a Rauzy fractal sequence: fixed
 *          point of the morphism 1 -> 12, 2 -> 13, 3 -> 1, starting from a(1)
 *          = 1.
 * https://oeis.org/A092782
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = 1 if n is in A003144, 2 if n is in A003145, 3 if n is in
 *            A003146 (the ternary Tribonacci word generated by the morphism
 *            1→12, 2→13, 3→1). The following implementation builds the word
 *            iteratively and caches it between calls
 * Range:     u8 n <= 9579, u16 n <= 9579, u32 n <= 9579, u64 n <= 9579,
 *            u128 n <= 9579, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* cache for the word; expanded only when a larger n is requested */
static seq_t *trib_cache = NULL;   /* symbol sequence */
static size_t  trib_len  = 0;      /* current number of symbols in the word */

/* Expand trib_cache until it contains at least target_len symbols. */
static void trib_expand(idx_t target_len)
{
    /* Fast‑path for initialisation. */
    if (trib_cache == NULL) {
        trib_cache = (seq_t *)malloc(sizeof(seq_t));
        if (trib_cache == NULL) abort();          /* allocation failed */
        trib_cache[0] = (seq_t)1;                 /* start with symbol 1 */
        trib_len = 1;
    }

    while (trib_len < (size_t)target_len) {
        /* Allocate a new buffer with enough capacity for the next step */
        size_t new_cap = trib_len * 2 + 4;          /* 2× expansion plus a margin */
        seq_t *new_cache = (seq_t *)malloc(new_cap * sizeof(seq_t));
        if (new_cache == NULL) abort();

        size_t pos = 0;
        for (size_t i = 0; i < trib_len; ++i) {
            seq_t s = trib_cache[i];
            if (s == (seq_t)1) {               /* 1 → 12 */
                new_cache[pos++] = (seq_t)1;
                new_cache[pos++] = (seq_t)2;
            } else if (s == (seq_t)2) {          /* 2 → 13 */
                new_cache[pos++] = (seq_t)1;
                new_cache[pos++] = (seq_t)3;
            } else {                            /* 3 → 1 */
                new_cache[pos++] = (seq_t)1;
            }
        }

        /* Release the old word and update the cache */
        free(trib_cache);
        trib_cache = new_cache;
        trib_len   = pos;
    }
}

seq_t a(idx_t n)
{
    if (n <= 0) return (seq_t)0;        /* undefined for n <= 0 */
    trib_expand(n);
    return trib_cache[n - 1];
}
